with flattened_attrs as (select id, coupon_codes, items, ship_to, attributes, array_contains(coupon_codes, 'WELCOME5') as used_welcome5, array_max(transform(items, li -> li.price)) as max_item_price, attributes['utm_source'] as utm_source, size(attributes) as num_attributes from carts) select id, coupon_codes, used_welcome5, max_item_price, utm_source, num_attributes, avg(max_item_price) over (order by num_attributes, id rows between unbounded preceding and current row) as running_avg_max_item_price, min(max_item_price) over (order by num_attributes, id rows between unbounded preceding and current row) as running_min_max_item_price, max(max_item_price) over (order by num_attributes, id rows between unbounded preceding and current row) as running_max_max_item_price from flattened_attrs
